"use client";
import React, { useState, useEffect } from "react";
import Link from "next/link";
import { Wallet, TrendingUp, TrendingDown, PiggyBank, ArrowRight, Sparkles, Bot, } from "lucide-react";
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, PieChart, Pie, Cell, } from "recharts";
import { useAuth } from "@/context/AuthContext";
import { useTheme } from "@/context/ThemeContext";
import { CategoryIcon } from "@/components/CategoryIcon";
import { StudentPacingCard } from "@/components/StudentPacingCard";
import { ForecastWidget } from "@/components/ForecastWidget";
import { GamificationWidget } from "@/components/GamificationWidget";
import { EmergencyFundCard } from "@/components/EmergencyFundCard";
import { WhatIfSimulatorModal } from "@/components/WhatIfSimulatorModal";
import { HelpCircle } from "lucide-react";

export default function DashboardPage() {
    const { user } = useAuth();
    const { theme } = useTheme();
    const currency = user?.currency || "₹";
    const [period, setPeriod] = useState("THIS_MONTH");
    const [loading, setLoading] = useState(true);
    const [analyticsData, setAnalyticsData] = useState(null);
    const [goals, setGoals] = useState([]);
    const [recentTx, setRecentTx] = useState([]);
    const [budgetsData, setBudgetsData] = useState(null);
    const [aiInsights, setAiInsights] = useState(null);
    const [isSimulatorOpen, setIsSimulatorOpen] = useState(false);
    const fetchData = async () => {
        setLoading(true);
        try {
            const [analyticsRes, goalsRes, txRes, budgetsRes] = await Promise.all([
                fetch(`/api/analytics?period=${period}`),
                fetch("/api/goals"),
                fetch("/api/transactions?limit=5"),
                fetch("/api/budgets"),
            ]);
            if (analyticsRes.ok)
                setAnalyticsData(await analyticsRes.json());
            if (goalsRes.ok) {
                const gData = await goalsRes.json();
                setGoals(gData.goals || []);
            }
            if (txRes.ok) {
                const tData = await txRes.json();
                setRecentTx(tData.transactions || []);
            }
            if (budgetsRes.ok) {
                setBudgetsData(await budgetsRes.json());
            }
        }
        catch (err) {
            console.error(err);
        }
        finally {
            setLoading(false);
        }
        // Fetch AI Advisor Insights asynchronously in background to ensure zero render lag
        fetch("/api/ai/advisor")
            .then((res) => (res.ok ? res.json() : null))
            .then((data) => {
            if (data)
                setAiInsights(data);
        })
            .catch((err) => console.error("AI Advisor fetch background error:", err));
    };
    useEffect(() => {
        fetchData();
    }, [period]);
    useEffect(() => {
        const handleUpdate = () => fetchData();
        window.addEventListener("fintrack_data_updated", handleUpdate);
        return () => window.removeEventListener("fintrack_data_updated", handleUpdate);
    }, [period]);
    const summary = analyticsData?.summary || { totalIncome: 0, totalExpenses: 0, netSavings: 0, savingsRate: 0 };
    const totalBalance = (summary.totalIncome || 0) - (summary.totalExpenses || 0);
    const CHERRY_PALETTE = ["#810100", "#630000", "#9E100E", "#B22222", "#4A0000", "#D32F2F", "#8B0000"];
    return (<div className="space-y-8 animate-in fade-in duration-300">
      {/* Header & Time Period Selector */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl md:text-3xl font-black tracking-tight text-[#141010] dark:text-[#FAF8F5]">
            Welcome back, {user?.name || "Megha R"}
          </h1>
          <p className="text-xs md:text-sm text-[#4A3F3F] dark:text-[#C8BFB0] font-medium mt-1">
            FinTrack Intelligence • Real-time metrics and cash flow analysis.
          </p>
        </div>

        {/* Time Period Filter Pills & What-If Simulator Trigger */}
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={() => setIsSimulatorOpen(true)}
            className="px-4 py-2 rounded-2xl text-xs font-black bg-gradient-to-r from-amber-500 to-orange-600 text-white shadow-md flex items-center gap-1.5 hover:opacity-95 transition"
          >
            <Sparkles className="w-3.5 h-3.5" />
            <span>Can I Afford This?</span>
          </button>
          <div className="flex items-center gap-1.5 p-1.5 bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] rounded-2xl shadow-sm overflow-x-auto">
            {[
              { id: "THIS_WEEK", label: "This Week" },
              { id: "THIS_MONTH", label: "This Month" },
              { id: "LAST_MONTH", label: "Last Month" },
              { id: "LAST_3_MONTHS", label: "Last 3M" },
              { id: "THIS_YEAR", label: "This Year" },
          ].map((item) => (<button key={item.id} onClick={() => setPeriod(item.id)} className={`px-3.5 py-1.5 rounded-xl text-xs font-extrabold transition-all whitespace-nowrap ${period === item.id
                  ? "bg-gradient-to-r from-[#810100] to-[#630000] text-white shadow-md cherry-glow"
                  : "text-[#4A3F3F] dark:text-[#C8BFB0] hover:text-[#141010] dark:hover:text-[#FAF8F5]"}`}>
                {item.label}
              </button>))}
          </div>
        </div>
      </div>

      {/* KPI Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Total Balance Card */}
        <div className="p-6 rounded-3xl bg-gradient-to-br from-[#810100] via-[#630000] to-[#810100] text-white border border-[#810100]/60 shadow-xl cherry-glow relative overflow-hidden flex flex-col justify-between">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold tracking-widest text-[#FAF8F5]/90 uppercase">Total Net Balance</span>
            <div className="w-9 h-9 rounded-2xl bg-white/20 flex items-center justify-center text-white backdrop-blur-md">
              <Wallet className="w-4.5 h-4.5"/>
            </div>
          </div>
          <div className="mt-4">
            <span className="font-heading text-3xl md:text-4xl font-black tracking-tight">
              {currency}{totalBalance.toLocaleString()}
            </span>
          </div>
          <div className="mt-3 pt-3 border-t border-white/15 flex items-center justify-between text-[11px] text-[#FAF8F5]/90 font-semibold">
            <span>Cumulative Net Capital</span>
            <span className="px-2 py-0.5 rounded-full bg-white/20 backdrop-blur-sm text-white font-extrabold text-[10px]">
              Live Track
            </span>
          </div>
        </div>

        {/* Total Income Card */}
        <div className="p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold tracking-widest text-[#4A3F3F] dark:text-[#C8BFB0] uppercase">Total Income</span>
            <div className="w-9 h-9 rounded-2xl bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 flex items-center justify-center font-bold">
              <TrendingUp className="w-4 h-4"/>
            </div>
          </div>
          <div className="mt-4">
            <span className="text-3xl font-black text-emerald-700 dark:text-emerald-400">
              {currency}{(summary.totalIncome || 0).toLocaleString()}
            </span>
          </div>
          <div className="mt-2 text-[11px] text-[#594D4D] dark:text-[#8C8080] font-medium">
            Inflow for selected period
          </div>
        </div>

        {/* Total Expenses Card */}
        <div className="p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold tracking-widest text-[#4A3F3F] dark:text-[#C8BFB0] uppercase">Total Expenses</span>
            <div className="w-9 h-9 rounded-2xl bg-[#810100]/10 text-[#810100] dark:text-[#E53835] flex items-center justify-center font-bold">
              <TrendingDown className="w-4 h-4"/>
            </div>
          </div>
          <div className="mt-4">
            <span className="text-3xl font-black text-[#810100] dark:text-[#E53835]">
              {currency}{(summary.totalExpenses || 0).toLocaleString()}
            </span>
          </div>
          <div className="mt-2 text-[11px] text-[#594D4D] dark:text-[#8C8080] font-medium">
            Outflow for selected period
          </div>
        </div>

        {/* Savings Rate Card */}
        <div className="p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold tracking-widest text-[#4A3F3F] dark:text-[#C8BFB0] uppercase">Savings Rate</span>
            <div className="w-9 h-9 rounded-2xl bg-[#810100]/10 text-[#810100] dark:text-[#FAF8F5] flex items-center justify-center font-bold">
              <PiggyBank className="w-4 h-4"/>
            </div>
          </div>
          <div className="mt-4 flex items-baseline justify-between">
            <span className="text-3xl font-black text-[#141010] dark:text-[#FAF8F5]">
              {currency}{(summary.netSavings || 0).toLocaleString()}
            </span>
            <span className="text-xs font-black px-2.5 py-1 rounded-full bg-[#810100]/15 text-[#810100] dark:text-[#FAF8F5] border border-[#810100]/30">
              {summary.savingsRate}%
            </span>
          </div>
          <div className="mt-2 text-[11px] text-[#594D4D] dark:text-[#8C8080] font-medium">
            Net saved percentage
          </div>
        </div>
      </div>

      {/* Hostel Student Budget Pacing Card */}
      {budgetsData && <StudentPacingCard summary={budgetsData.summary}/>}

      {/* AI Velocity Forecast & Gamification Streaks */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <ForecastWidget currency={currency} />
        <GamificationWidget />
      </div>

      {/* Emergency Reserve Bucket */}
      <EmergencyFundCard currency={currency} />

      {/* AI Financial Snapshot Card */}
      {aiInsights && aiInsights.insights && aiInsights.insights.length > 0 && (<div className="p-6 rounded-3xl bg-gradient-to-r from-[#810100] via-[#630000] to-[#810100] dark:from-[#201A1A] dark:via-[#141010] dark:to-[#201A1A] text-white dark:text-[#FAF8F5] border border-[#810100]/40 shadow-xl relative overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-2xl bg-white/20 dark:bg-[#FAF8F5]/20 text-white flex items-center justify-center shadow-md">
                <Bot className="w-5 h-5"/>
              </div>
              <div>
                <h3 className="font-heading font-extrabold text-base text-white dark:text-[#FAF8F5]">FinTrack AI Advisor Insights</h3>
                <p className="text-xs text-white/80 dark:text-[#C8BFB0]">Automated observations grounded in your transaction history</p>
              </div>
            </div>
            <Link href="/ai-advisor" className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white/20 hover:bg-white/30 text-white dark:text-[#FAF8F5] text-xs font-extrabold transition-all backdrop-blur-sm shadow-sm">
              <span>Launch AI Assistant</span>
              <ArrowRight className="w-3.5 h-3.5"/>
            </Link>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {aiInsights.insights.map((insight, idx) => (<Link key={idx} href={`/ai-advisor`} className="p-4 rounded-2xl bg-black/20 dark:bg-[#141010]/80 border border-white/20 dark:border-[#3B3030] backdrop-blur-sm flex flex-col justify-between hover:bg-black/30 transition-all group">
                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <div className="flex items-center gap-2 text-xs font-bold text-white dark:text-[#FAF8F5]">
                      <Sparkles className="w-3.5 h-3.5 text-white dark:text-[#E53835]"/>
                      <span>{insight.title}</span>
                    </div>
                    <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-white/20 text-white uppercase tracking-wider">
                      {insight.category}
                    </span>
                  </div>
                  <p className="text-xs text-white/90 dark:text-[#C8BFB0] leading-relaxed">{insight.text}</p>
                </div>
                <div className="mt-3 pt-2 border-t border-white/10 flex items-center justify-end text-[11px] font-bold text-white/80 group-hover:text-white">
                  <span>Analyze in Chat ➔</span>
                </div>
              </Link>))}
          </div>
        </div>)}

      {/* Recharts Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Income vs Expenses Bar Chart */}
        <div className="lg:col-span-2 p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm flex flex-col justify-between">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h3 className="font-extrabold text-base text-[#141010] dark:text-[#FAF8F5]">Monthly Cash Flow</h3>
              <p className="text-xs text-[#594D4D] dark:text-[#8C8080]">Income vs Expenses (Last 6 Months)</p>
            </div>
          </div>

          <div className="h-64 w-full">
            {analyticsData?.monthlyTrend && (<ResponsiveContainer width="100%" height="100%">
                <BarChart data={analyticsData.monthlyTrend}>
                  <XAxis dataKey="month" stroke={theme === "dark" ? "#887B7B" : "#594D4D"} fontSize={11}/>
                  <YAxis stroke={theme === "dark" ? "#887B7B" : "#594D4D"} fontSize={11}/>
                  <Tooltip contentStyle={{
                backgroundColor: theme === "dark" ? "#141010" : "#FFFFFF",
                borderColor: theme === "dark" ? "#3B3030" : "#E2DBD0",
                borderRadius: "14px",
                color: theme === "dark" ? "#FAF8F5" : "#141010",
                fontSize: "12px",
            }}/>
                  <Bar dataKey="income" fill="#10b981" radius={[6, 6, 0, 0]} name="Income"/>
                  <Bar dataKey="expenses" fill="#810100" radius={[6, 6, 0, 0]} name="Expenses"/>
                </BarChart>
              </ResponsiveContainer>)}
          </div>
        </div>

        {/* Expense Category Breakdown Pie Chart */}
        <div className="p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm flex flex-col justify-between">
          <div>
            <h3 className="font-extrabold text-base text-[#141010] dark:text-[#FAF8F5]">Category Outflow</h3>
            <p className="text-xs text-[#594D4D] dark:text-[#8C8080]">Top spending categories</p>
          </div>

          <div className="h-52 w-full my-2">
            {analyticsData?.categoryBreakdown && analyticsData.categoryBreakdown.length > 0 ? (<ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={analyticsData.categoryBreakdown} dataKey="amount" nameKey="name" cx="50%" cy="50%" innerRadius={45} outerRadius={75} paddingAngle={4}>
                    {analyticsData.categoryBreakdown.map((entry, index) => (<Cell key={`cell-${index}`} fill={CHERRY_PALETTE[index % CHERRY_PALETTE.length]}/>))}
                  </Pie>
                  <Tooltip formatter={(value) => `${currency}${value.toLocaleString()}`} contentStyle={{
                backgroundColor: theme === "dark" ? "#141010" : "#FFFFFF",
                borderColor: theme === "dark" ? "#3B3030" : "#E2DBD0",
                borderRadius: "14px",
                color: theme === "dark" ? "#FAF8F5" : "#141010",
                fontSize: "12px",
            }}/>
                </PieChart>
              </ResponsiveContainer>) : (<div className="h-full flex items-center justify-center text-xs text-[#594D4D]">
                No expense entries logged for this period
              </div>)}
          </div>

          {/* Mini Legend List */}
          <div className="space-y-2 max-h-28 overflow-y-auto pr-1">
            {analyticsData?.categoryBreakdown?.slice(0, 4).map((cat, idx) => (<div key={idx} className="flex items-center justify-between text-xs">
                <div className="flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: CHERRY_PALETTE[idx % CHERRY_PALETTE.length] }}/>
                  <span className="font-bold text-[#4A3F3F] dark:text-[#C8BFB0]">{cat.name}</span>
                </div>
                <span className="font-black text-[#141010] dark:text-[#FAF8F5]">
                  {currency}{cat.amount.toLocaleString()} ({cat.percentage}%)
                </span>
              </div>))}
          </div>
        </div>
      </div>

      {/* Grid: Financial Goals & Recent Transactions */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Financial Goals Progress */}
        <div className="p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="font-extrabold text-base text-[#141010] dark:text-[#FAF8F5]">Financial Goals</h3>
            <Link href="/goals" className="text-xs font-extrabold text-[#810100] dark:text-[#FAF8F5] hover:underline">
              View All
            </Link>
          </div>

          <div className="space-y-4">
            {goals.slice(0, 3).map((goal) => (<div key={goal.id} className="p-4 rounded-2xl bg-[#FAF8F5] dark:bg-[#141010]/60 border border-[#E2DBD0] dark:border-[#3B3030] space-y-2">
                <div className="flex items-center justify-between text-xs font-extrabold text-[#141010] dark:text-[#FAF8F5]">
                  <span>{goal.title}</span>
                  <span className="text-[#810100] dark:text-[#FAF8F5]">{goal.percentageCompleted}%</span>
                </div>
                <div className="w-full bg-[#E2DBD0] dark:bg-[#3B3030] h-2.5 rounded-full overflow-hidden">
                  <div className="bg-[#810100] h-full rounded-full transition-all duration-500" style={{ width: `${goal.percentageCompleted}%` }}/>
                </div>
                <div className="flex items-center justify-between text-[11px] text-[#594D4D] dark:text-[#8C8080] font-semibold">
                  <span>
                    Saved: {currency}{goal.currentAmount.toLocaleString()}
                  </span>
                  <span>Target: {currency}{goal.targetAmount.toLocaleString()}</span>
                </div>
              </div>))}
          </div>
        </div>

        {/* Recent Transactions List */}
        <div className="lg:col-span-2 p-6 rounded-3xl bg-[#FFFFFF] dark:bg-[#201A1A] border border-[#E2DBD0] dark:border-[#3B3030] shadow-sm space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="font-extrabold text-base text-[#141010] dark:text-[#FAF8F5]">Recent Activity</h3>
            <Link href="/transactions" className="text-xs font-extrabold text-[#810100] dark:text-[#FAF8F5] hover:underline">
              View All Transactions
            </Link>
          </div>

          <div className="divide-y divide-[#E2DBD0]/50 dark:divide-[#3B3030]">
            {recentTx.map((tx) => (<div key={tx.id} className="py-3.5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-2xl flex items-center justify-center text-white shrink-0 shadow-sm" style={{ backgroundColor: tx.category?.color || "#810100" }}>
                    <CategoryIcon iconName={tx.category?.icon || "Tag"} className="w-5 h-5"/>
                  </div>
                  <div>
                    <h4 className="font-bold text-xs md:text-sm text-[#141010] dark:text-[#FAF8F5]">{tx.description}</h4>
                    <div className="flex items-center gap-2 text-[11px] text-[#594D4D] dark:text-[#8C8080]">
                      <span>{tx.category?.name}</span>
                      <span>•</span>
                      <span>{new Date(tx.date).toLocaleDateString()}</span>
                      <span>•</span>
                      <span className="px-2 py-0.5 rounded-md bg-[#FAF8F5] dark:bg-[#141010] font-semibold border border-[#E2DBD0] dark:border-[#3B3030]">
                        {tx.paymentMethod}
                      </span>
                    </div>
                  </div>
                </div>
                <div className={`font-black text-sm md:text-base ${tx.type === "INCOME" ? "text-emerald-700 dark:text-emerald-400" : "text-[#810100] dark:text-[#FAF8F5]"}`}>
                  {tx.type === "INCOME" ? "+" : "-"}
                  {currency}
                  {tx.amount.toLocaleString()}
                </div>
              </div>))}
          </div>
        </div>
      </div>

      <WhatIfSimulatorModal
        isOpen={isSimulatorOpen}
        onClose={() => setIsSimulatorOpen(false)}
      />
    </div>);
}
